import random, time

class CircuitBreaker:
    def __init__(self, failure_threshold=5, max_retries=2, base_delay=0.1, reset_timeout=30.0):
        self.failure_threshold, self.max_retries = failure_threshold, max_retries
        self.base_delay, self.reset_timeout, self.failures, self.opened_at = base_delay, reset_timeout, 0, None

    def call(self, fn, *args, **kwargs):
        if self.opened_at and time.monotonic() - self.opened_at < self.reset_timeout:
            raise RuntimeError("Circuit breaker is OPEN")
